"""Справочник упражнений для приложения: только книга Ли (+ помеченные вставки)."""

EX = {}
GROUPS = ["Разминка и суставы", "Ноги", "Спина и всё тело", "Грудь, плечи, руки", "Предплечья и хват",
          "Пресс и талия", "Общефизическая программа Ли", "Изометрия", "Раунды: тень, скакалка, груша",
          "Бег и кардио", "Растяжка и дыхание"]


def E(i, name, group, page, wt, how, err="", alt=""):
    assert i not in EX, i
    assert group in GROUPS, group
    EX[i] = {"name": name, "group": group, "page": page, "wt": wt, "how": how, "err": err, "alt": alt}


